-- Title: Office Autorun Keys Modification
-- ID: baecf8fb-edbf-429f-9ade-31fc3f22b970
-- Status: test
-- Level: medium
-- Author: Victor Sergeev, Daniil Yugoslavskiy, Gleb Sukhodolskiy, Timur Zinniatullin, oscd.community, Tim Shelton, frack113 (split)
-- Date: 2019-10-25
-- Tags: attack.privilege-escalation, attack.persistence, attack.t1547.001
-- Description: Detects modification of autostart extensibility point (ASEP) in registry. Adversaries may modify these keys to execute malicious code when Office files are opened.
-- There are various legitimate add-ins that also use these keys and this filter list might not be exhaustive.
-- Thus, it is recommended to review and tune filters for your environment to reduce false positives before deploying to production.
-- Converted by: Sigma Universal SIEM/EDR CLI

SELECT * FROM file WHERE ((((TargetObject LIKE '%\\Word\\Addins%' OR TargetObject LIKE '%\\PowerPoint\\Addins%' OR TargetObject LIKE '%\\Outlook\\Addins%' OR TargetObject LIKE '%\\Onenote\\Addins%' OR TargetObject LIKE '%\\Excel\\Addins%' OR TargetObject LIKE '%\\Access\\Addins%' OR TargetObject LIKE '%test\\Special\\Perf%')) AND ((TargetObject LIKE '%\\Software\\Wow6432Node\\Microsoft\\Office%' OR TargetObject LIKE '%\\Software\\Microsoft\\Office%'))) AND NOT (((Details = '(Empty)') OR ((Image="C:\\Program Files\\Microsoft Office\\*" OR Image="C:\\Program Files (x86)\\Microsoft Office\\*" OR Image="C:\\PROGRA~2\\MICROS~2\\Office*" OR Image="C:\\Windows\\System32\\msiexec.exe*" OR Image="C:\\Windows\\SysWOW64\\msiexec.exe*" OR Image="C:\\Windows\\System32\\regsvr32.exe*" OR Image="C:\\Windows\\SysWOW64\\regsvr32.exe*") AND (TargetObject LIKE '%\\Excel\\Addins\\AdHocReportingExcelClientLib.AdHocReportingExcelClientAddIn.1\\%' OR TargetObject LIKE '%\\Excel\\Addins\\ExcelPlugInShell.PowerMapConnect\\%' OR TargetObject LIKE '%\\Excel\\Addins\\NativeShim\\%' OR TargetObject LIKE '%\\Excel\\Addins\\NativeShim.InquireConnector.1\\%' OR TargetObject LIKE '%\\Excel\\Addins\\PowerPivotExcelClientAddIn.NativeEntry.1\\%' OR TargetObject LIKE '%\\Outlook\\AddIns\\AccessAddin.DC\\%' OR TargetObject LIKE '%\\Outlook\\AddIns\\ColleagueImport.ColleagueImportAddin\\%' OR TargetObject LIKE '%\\Outlook\\AddIns\\EvernoteCC.EvernoteContactConnector\\%' OR TargetObject LIKE '%\\Outlook\\AddIns\\EvernoteOLRD.Connect\\%' OR TargetObject LIKE '%\\Outlook\\Addins\\OneNote.OutlookAddin%' OR TargetObject LIKE '%\\Outlook\\Addins\\DriveFSExtensionLib.Connect\\%' OR TargetObject LIKE '%\\Outlook\\Addins\\GoogleAppsSync.Connect\\%' OR TargetObject LIKE '%\\Outlook\\Addins\\Microsoft.VbaAddinForOutlook.1\\%' OR TargetObject LIKE '%\\Outlook\\Addins\\OcOffice.OcForms\\%' OR TargetObject LIKE '%\\Outlook\\Addins\\OscAddin.Connect\\%' OR TargetObject LIKE '%\\Outlook\\Addins\\OutlookChangeNotifier.Connect\\%' OR TargetObject LIKE '%\\Outlook\\Addins\\UCAddin.LyncAddin.1%' OR TargetObject LIKE '%\\Outlook\\Addins\\UCAddin.UCAddin.1%' OR TargetObject LIKE '%\\Outlook\\Addins\\UmOutlookAddin.FormRegionAddin\\%' OR TargetObject LIKE '%AddinTakeNotesService\\FriendlyName%')) OR (NOT Details=*) OR ((Image="C:\\Program Files\\Common Files\\Microsoft Shared\\ClickToRun\\*" OR Image="C:\\Program Files\\Common Files\\Microsoft Shared\\ClickToRun\\Updates\\*") AND Image="*\\OfficeClickToRun.exe") OR ((Image="C:\\Program Files\\Common Files\\Microsoft Shared\\VSTO\\*" OR Image="C:\\Program Files (x86)\\Microsoft Shared\\VSTO\\*") AND Image="*\\VSTOInstaller.exe"))) AND NOT ((((Image = 'C:\\Program Files\\Avast Software\\Avast\\RegSvr.exe' OR Image = 'C:\\Program Files\\Avast Software\\Avast\\x86\\RegSvr.exe') AND TargetObject LIKE '%\\Microsoft\\Office\\Outlook\\Addins\\Avast.AsOutExt\\%') OR ((Image = 'C:\\Program Files\\AVG\\Antivirus\\RegSvr.exe' OR Image = 'C:\\Program Files\\AVG\\Antivirus\\x86\\RegSvr.exe') AND TargetObject LIKE '%\\Microsoft\\Office\\Outlook\\Addins\\Antivirus.AsOutExt\\%'))))
